    graph_copy = {k: v.copy() for k, v in graph.items()}
    del graph_copy[city_to_destroy]
    for u in graph:
        graph_copy[u] = [(v, w) for v, w in graph[u] if v != city_to_destroy]

    # New shortest paths after destruction
    new_dist = dijkstra(s, graph_copy)

    # Friends are unhappy if:
    # 1. Their city is destroyed (city_to_destroy), or
    # 2. Their city was reachable before but not after, or
    # 3. Their city's shortest path increased
    unhappy = 0
    for friend_city in range(1, n + 1):
        if friend_city == s:
            continue
        if friend_city == city_to_destroy:
            unhappy += 1
        elif original_dist[friend_city] != float('inf') and (new_dist[friend_city] == float('inf') or new_dist[friend_city] > original_dist[friend_city]):
            unhappy += 1
    return unhappy

def dijkstra(start, graph):
    dist = {city: float('inf') for city in graph}
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return dist

